+		head = (x >= fs->secpertrack) ? 1 : 0;
+		sector = x % fs->secpertrack;
+		n = min(sectors_nb, fs->secpertrack - sector);
+
+		swim_track(fs, cyl);
+		swim_head(base, head);
+
+		ret = swim_read_sector_range(fs, head, cyl, sector + 1, n, buffer);
+		if (ret != n)
+			++failures;
+		if (failures >= 5)
+			return BLK_STS_IOERR;
+
+		buffer += 512 * ret;
+		sectors_nb -= ret;
+		req_sector += ret;
 	}
 
 	return 0;
